        TextChunk mergedChunk = chunk1.merge(chunk2);

        // Assert that the returned object is the same instance as chunk1
        assertSame(chunk1, mergedChunk);

        // Assert that the merged chunk's properties have been updated correctly
        // The expected behavior of super.merge is to adjust the rectangle's boundaries
        // to encompass both rectangles.

        // Calculate the expected bounding box
        float expectedTop = Math.min(10, 15);
        float expectedLeft = Math.min(20, 25);
        float expectedRight = Math.max(20 + 30, 25 + 35);
        float expectedBottom = Math.max(10 + 40, 15 + 45);

        float expectedWidth = expectedRight - expectedLeft;
        float expectedHeight = expectedBottom - expectedTop;

        assertEquals(expectedTop, mergedChunk.getTop(), 0.001);
        assertEquals(expectedLeft, mergedChunk.getLeft(), 0.001);
